(3, 1, 1, 'Welcome to SkillikS', 'welcome-to-skilliks', '', 'Welcome to Skilliks. This site was developed 100% using vibe coding with Claude Code using techniques you will learn in this community.  The first step is to take the skills survey.', NULL, '', '', 'published', 'community', 1, 0, 0, 218, 35, 0, '', '', '2025-07-24 13:09:54', '2025-07-24 17:09:54', '2026-01-05 01:19:22'),
(4, 1, 1, 'Professional Live Call - Aug 10, 2025', 'professional-live-call-aug-10-2025', '', 'This is the live call from August 10, 2025 where we covered the development of MCP servers.', NULL, 'https://youtu.be/jeAUYg-UOQc', '', 'published', 'community', 1, 0, 0, 37, 3, 0, '', '', '2025-08-11 16:55:55', '2025-08-11 20:55:55', '2026-01-05 00:48:52'),
(5, 1, 1, 'Free Live Call - August 9, 2025', 'free-live-call-august-9-2025', '', 'At this event we covered running local models with Ollama and LM Studio.', NULL, 'https://youtu.be/t-0EDfavJec', '', 'published', 'community', 1, 0, 0, 26, 4, 0, '', '', '2025-08-11 17:08:10', '2025-08-11 21:08:10', '2026-01-05 01:35:24'),
(6, 1, 1, 'Vibe Coding Master Class - Part 1', 'vibe-coding-master-class-part-1', '', 'Vibe coding master class part 1.', NULL, 'https://youtu.be/nkiP-G8e9lw', '', 'published', 'community', 1, 0, 0, 88, 3, 0, '', '', '2025-08-20 13:50:41', '2025-08-20 17:50:41', '2026-01-08 21:28:16');
