INSERT INTO `communities` (`id`, `name`, `slug`, `description`, `logo_url`, `banner_url`, `settings`, `is_active`, `is_public`, `requires_approval`, `auto_approve_from_email_list`, `requires_skool_registration`, `skool_url`, `monthly_price`, `display_member_count`, `created_by`, `created_at`, `updated_at`) VALUES
(1, 'AI Masters Professional', 'ai-masters-pro', 'The AI Masters Professional Community was founded by Edward Honour to change the way Artificial Intelligence is taught and the way AI projects are managed.  In the professional community members of all experience levels work on real world projects.', '', 'https://images.skilliks.ai/masters-landing.jpg', NULL, 1, 1, 0, 0, 1, 'https://www.skool.com/edward-honour/about', 99.00, '', 1, '2025-07-17 15:21:23', '2025-08-11 20:34:12'),
(2, 'AI Masters Community - Free', 'ai-masters-community', 'This is the AI Masters free community for members of all skill levels.  The Masters Free Community contains the same courses as the AI Masters Professional Community but does not include real-world projects and as many live sessions.  This is the perfect free community to join to decide if AI is right for you.', '', 'https://images.skilliks.ai/masters-ed-logo.jpg', NULL, 1, 1, 1, 1, 0, NULL, 0.00, NULL, 1, '2025-07-18 06:56:30', '2025-08-12 01:14:09');
