(9, 1, 'AI Basics', NULL, 'This course provides a basic foundation of AI technologies.', 'This course provides a basic foundation of AI technologies.', '', 'Beginners', 5, 'beginner', 0.00, '', '', 'published', 0, 'https://images.skilliks.ai/ai-fund.jpg', 1, '2025-07-24 15:46:10', '2025-07-28 21:04:20', NULL, 0, '', 0, 70.00),
(10, 1, 'Our Learning Approach', NULL, 'This course contains an overview presentation of the theory and concepts behind our learning approach.', 'This course contains an overview presentation of the theory behind our learning approach.', '', 'Introduction', 6, 'beginner', 0.00, '', '', 'published', 1, 'https://images.skilliks.ai/approach.jpg', 1, '2025-07-24 17:03:44', '2025-07-28 18:08:12', NULL, 0, '', 0, 70.00),
(11, 1, 'Basic HTML & CSS', NULL, 'In this course you will learn the basics of html and css.  The goal is to understand HTML and CSS enough to vibe code basic web pages effectively.', 'This is a beginners course to give you the basic knowledge necessary to create and debug web pages.  It provides the basics necessary for vibe coding.', '', 'Web Design', 5, 'beginner', 0.00, 'None', 'Ability to read HTML and CSS', 'published', 0, 'https://images.skilliks.ai/html-3.jpg', 1, '2025-07-27 01:43:04', '2025-07-28 21:46:45', NULL, 0, 'HTML, CSS', 0, 70.00),
(15, 1, 'Creating Your Learning Strategy', NULL, 'Learn the process of planning your AI learning strategy.', 'This course takes you step by step through the process of creating your learning strategy.', '', '', NULL, 'beginner', 0.00, '', '', 'published', 0, 'https://images.skilliks.ai/learning-strategy.jpg', 1, '2025-07-28 18:01:11', '2025-07-28 20:59:02', NULL, 0, '', 0, 70.00),
