(23, 1, 'Supervised Fine Tuning', NULL, 'Supervised Fine Tuning is the process of customizing open source models with additional information.', 'Supervised Fine Tuning is the process of customizing open source models with additional information.', '', '', 3, 'beginner', 0.00, '', '', 'published', 0, 'https://images.skilliks.ai/sft-3.jpg', 1, '2025-07-28 19:03:59', '2025-07-28 19:06:11', NULL, 0, '', 0, 70.00),
(24, 1, 'Knowledge Graphs', NULL, 'A knowledge graph is a structured representation of information that connects entities (like people, places, or concepts) through labeled relationships, enabling machines to understand and reason about data more effectively.', 'Learn about knowledge graphs and graph databases.', '', '', 3, 'beginner', 0.00, '', '', 'published', 0, 'https://images.skilliks.ai/kg-2.jpg', 1, '2025-07-28 19:10:05', '2025-07-28 19:10:05', NULL, 0, '', 0, 70.00),
