(43, 9, 1, 'AI Automation Manager Template', 'ai-automation-manager-template', 'A template for building dashboards for AI automations.', 'https://images.skilliks.ai/aiauto.jpg', '', NULL, '', 10, NULL, NULL, 'active', 'public', 'https://skilliks.fan11.com', 'https://skilliks.fan11.com', NULL, 0, NULL, 1, NULL, '2025-09-14 01:52:24', '2025-09-14 13:28:22', '', '', NULL, NULL),
(44, 9, 1, 'React-Native Mobile App Template', 'react-native-mobile-app-template', 'A starting point for react native mobile applications.', 'https://images.skilliks.ai/react-native.jpg', '', NULL, '', 10, NULL, NULL, 'active', 'public', '', NULL, NULL, 0, NULL, 1, NULL, '2025-09-14 02:24:01', '2025-09-14 02:26:56', '', '', NULL, NULL),
(45, 1, 1, 'MentionIQ Enhanced - Live Web Intelligence Integration', 'mentioniq-enhanced-live-web-intelligence-integration', 'Enhance existing MentionIQ brand monitoring tool by adding Perplexity Search API as 4th monitoring source. Transform from AI-only mention tracking to comprehensive brand intelligence platform combining AI responses + real-time web mentions from 200B+ URLs. Target: Brand managers and marketing teams seeking complete mention visibility.', 'https://images.skilliks.ai/pending.jpg', '', NULL, '', 10, NULL, NULL, 'planning', 'private', NULL, NULL, NULL, 0, NULL, 70, NULL, '2025-09-26 01:51:14', '2025-09-26 01:51:14', NULL, NULL, NULL, NULL),
(46, 2, 1, 'ContentGaps AI', 'contentgaps-ai', 'AI-powered content opportunity discovery tool that analyzes competitor content gaps and identifies trending topics before they become oversaturated. Uses Perplexity Search API to find what content competitors have published that you haven\'t, surfaces emerging industry topics, and scores opportunities by potential impact. Target: Content marketing managers, SEO agencies, and B2B marketing teams.', 'https://images.skilliks.ai/pending.jpg', '', NULL, '', 10, NULL, NULL, 'planning', 'private', NULL, NULL, NULL, 0, NULL, 70, NULL, '2025-09-26 01:52:13', '2025-09-26 01:52:13', NULL, NULL, NULL, NULL),
(47, 2, 1, 'LocalIQ Monitor - Geographic Brand Intelligence Platform', 'localiq-monitor-geographic-brand-intelligence-platform', 'Location-based brand monitoring platform using Perplexity\'s geographic filtering to track mentions, competitor activities, and local search performance across specific cities/regions. Features multi-location dashboard with map visualization, local competitor intelligence, and franchise-friendly reporting. Target: Multi-location businesses, franchises, and local SEO agencies.', 'https://images.skilliks.ai/pending.jpg', '', NULL, '', 10, NULL, NULL, 'planning', 'private', NULL, NULL, NULL, 0, NULL, 70, NULL, '2025-09-26 01:54:21', '2025-09-26 01:54:21', NULL, NULL, NULL, NULL),
(48, 2, 1, 'SERPWatch Pro - Multi-Platform SERP Intelligence System', 'serpwatch-pro-multi-platform-serp-intelligence-system', 'Comprehensive SERP tracking platform monitoring keyword rankings across traditional search engines (Google, Bing) AND AI platforms (Perplexity, ChatGPT, Claude). Features real-time competitor activity detection, SERP feature intelligence, and advanced ranking analytics. Target: SEO agencies, enterprise marketing teams, and e-commerce businesses.', 'https://images.skilliks.ai/pending.jpg', '', NULL, '', 10, NULL, NULL, 'planning', 'private', NULL, NULL, NULL, 0, NULL, 70, NULL, '2025-09-26 01:56:02', '2025-09-26 01:56:02', NULL, NULL, NULL, NULL);
