(4, 1, 'Skills Assessment Survey', 'Help us understand your interests, skills, and availability to better match you with projects and learning opportunities.', 'skills', NULL, 'Use for assessing team member skills and competencies', 1, 1, NULL, '2025-07-23 15:20:42', '2025-08-19 02:30:26'),
(6, 1, 'Project Planning Survey', 'This survey helps determine the right architecture, technology stack, and requirements for your project. Your responses will be analyzed by AI to generate customized recommendations including CLAUDE.md and requirements.md files.', 'project', 'general', 'Use for all standard projects requiring basic configuration and setup information', 1, 1, NULL, '2025-08-09 16:35:21', '2025-08-19 02:30:26'),
(7, 1, 'SaaS and Browser Based Background Survey', 'This survey is use for traditional browser based SaaS applications.', 'project', 'requirements', 'This survey is used for browser based applications that can be used by the public or inside corporations.  The purpose of this survey is to ensure no important requirements are missing from the application.', 1, 0, 1, '2025-08-10 12:10:27', '2025-08-19 02:34:16'),
(17, 2, 'Skills Assessment Survey', 'Help us understand your interests, skills, and availability to better match you with projects and learning opportunities.', 'skills', NULL, 'Use for assessing team member skills and competencies', 1, 1, 1, '2025-07-23 15:20:42', '2025-08-19 02:30:26'),
(18, 2, 'Project Planning Survey', 'This survey helps determine the right architecture, technology stack, and requirements for your project. Your responses will be analyzed by AI to generate customized recommendations including CLAUDE.md and requirements.md files.', 'project', NULL, 'General purpose survey for project configuration', 1, 1, 1, '2025-08-09 16:35:21', '2025-08-19 02:30:26'),
(19, 2, 'SaaS and Browser Based Background Survey', '', 'project', NULL, 'General purpose survey for project configuration', 1, 0, 1, '2025-08-10 12:10:27', '2025-08-19 02:30:26'),
(20, 1, 'Requirements Project Survey', 'Project survey for requirements configuration', 'project', 'requirements', 'Use for projects that need detailed requirements gathering and specification', 1, 0, 1, '2025-08-19 02:23:28', '2025-08-19 02:30:26'),
(21, 1, 'Design notes Project Survey', 'Project survey for design-notes configuration', 'project', 'design-notes', 'Use for projects with complex design requirements or UI/UX focus', 1, 0, 1, '2025-08-19 13:30:43', '2025-08-19 13:30:43'),
