INSERT INTO `system_status` (`id`, `message`, `created_at`, `updated_at`, `is_active`) VALUES
(1, 'Welcome! We are currently adding features, courses, and projects to the system.  We are looking for project recommendations.  Please make any project recommendations you have into the projects section so the community can vote and prioritize projects.', '2025-07-27 03:10:19', '2025-07-27 03:13:04', 1);
INSERT INTO `tickets` (`id`, `ticket_number`, `user_id`, `assigned_to`, `category_id`, `subject`, `description`, `status`, `priority`, `created_at`, `updated_at`, `closed_at`, `last_reply_at`) VALUES
(3, '2025-000001', 4, NULL, 2, 'Test Issue', 'This is a test issue.', 'new', 'normal', '2025-07-31 21:55:38', '2025-07-31 21:55:38', NULL, NULL),
(4, '2025-000002', 119, NULL, 3, 'Make Skilliks Add to Homepage', 'Theres a way to make Skilliks into an app without using safari mobile. The user just needs to save it to Home Screen but the dev team needs to enable that mobile feature', 'new', 'normal', '2025-08-03 10:17:05', '2025-08-03 10:17:05', NULL, NULL),
(5, '2025-000003', 102, NULL, 2, 'Internet and Web Basics course, What is a server video (https://skilliks.ai/course-detail?id=39&lesson=107) not working', 'Internet and Web Basics course, What is a server video (https://skilliks.ai/course-detail?id=39&lesson=107) video not showing', 'new', 'normal', '2025-08-05 17:53:33', '2025-08-05 17:53:33', NULL, NULL),
(6, '2025-000004', 102, NULL, 2, 'Constantly being signed out of platform', 'I am constantly being signed out of platform after a couple of hours. Around 5 times in 8 hours period.', 'new', 'normal', '2025-08-05 22:17:13', '2025-08-05 22:17:13', NULL, NULL),
(7, '2025-000005', 135, NULL, 2, 'Various issues with Skilliks.ai', 'Not sure whether you know, but there\'s a ton of errors around the portal - feels like something may have regressed.', 'new', 'normal', '2025-08-06 21:01:16', '2025-08-06 21:01:16', NULL, NULL),
(8, '2025-000006', 119, NULL, 3, 'Skills required shortcut in orojects', 'When checking out a project n Skilliks there are a list of required skills. Instead of having to navigate out of the project and into the skills sections we can just connect each skill listed in the project directly to the Skilliks tutorial itself. Currently there is no function for that. It’s just shows a static list.', 'new', 'normal', '2025-08-07 08:24:47', '2025-08-07 08:24:47', NULL, NULL),
(9, '2025-000007', 137, NULL, 2, 'Survey link not available', 'When i click on the survey, it is unavailable.', 'new', 'high', '2025-08-08 02:13:16', '2025-08-08 02:13:16', NULL, NULL),
(10, '2025-000008', 145, NULL, 2, 'Issues with the Internet and Web basics program', 'Attempting to learn - however the first lesson What is a server loaded as a blank page after starting the lesson - since it never played , it would not allow access to a quiz. I skipped to the next available lesson on the Internet- watched it - and it would not load the quiz as it reverted back to the first lesson that did not load- and again did not have load a quiz for either the first or second lesson since lesson 1 never played -- Also the introduction lesson doesn\'t allow access to 3 only 26 minutes of Ed Honour video---and continues to show 0 minutes though it was completed -- so many issues I have created as a novice', 'new', 'normal', '2025-08-09 02:39:58', '2025-08-09 02:39:58', NULL, NULL),
(11, '2025-000009', 146, NULL, 1, 'I am interested in learning more about SFT, parameters fine tuning, vLLMs, Deep Learning Inference Engineer.', 'Hi, This is not an issue ticket, but just a request. I recently started my AI career, I am interested in the deep learning domain. I am interested in leaning the how to increase the LLM go fast, increasing throughput, lowering the latency, KV caching, etc. I know all the jargons but I never worked anything hands-on. I would be grateful if I can get a chance to learn more about vLLMs, SGLang, FlashInfer, CUDA. I am still a newbie, but very much interested in learning more about this domain.', 'new', 'normal', '2025-08-10 14:25:57', '2025-08-10 14:25:57', NULL, NULL),
(12, '2025-000010', 153, NULL, 1, 'Skills survey not available?', 'Hi, I\'m a paid AI Masters Pro Community+ member and signed up on day1 of opening, however, due to excessive work commitments, i was unable to leverage the community, training, resources etc to date.  \r\n\r\nHowever, now i\'ve returned to catch up, if you will.  I\'ve signed up on the new platform (obviously, as i\'m writing to you on it), but the skills survey appears to be unavailable right now.  \r\n\r\nPlease advise?\r\n\r\nN.B.  As an aside, wondering if all the skool content will migrate to this platform? Also why are some courses e.g. \'AI Agents & Automations\' greyed out?', 'new', 'high', '2025-08-11 13:34:57', '2025-08-11 13:34:57', NULL, NULL),
(13, '2025-000011', 162, NULL, 2, 'Survey', 'I just registered - and then logged in, there is no survey found, there are no courses. I registered with my skool email address. I am a paid member of the pro community in Skool.', 'new', 'normal', '2025-08-11 22:49:15', '2025-08-11 22:49:15', NULL, NULL),
(14, '2025-000012', 210, NULL, 1, 'Lessons', 'Learning about servers video seems to be down.', 'new', 'normal', '2025-08-23 18:24:40', '2025-08-23 18:24:40', NULL, NULL),
(15, '2025-000013', 88, NULL, 2, 'Survey not quite working', 'Submitted new project SWEA.ai.   Trying to submit the survey, it says survey 100% submitted but then the purpose and techstack sections go blank.   I cannot tell if it saved these fields or not.  I have tried to copy and paste these sections a few times it still clears out once i press submit.', 'new', 'normal', '2025-08-24 04:53:52', '2025-08-24 04:53:52', NULL, NULL),
(16, '2025-000014', 220, NULL, 2, 'Submit new project failed on category', 'I\'m on a Chromebook, trying to submit my first project, and the \"category\" drop down menu isn\'t showing anything. Should I try using a different browser/OS?', 'new', 'normal', '2025-08-25 23:27:04', '2025-08-25 23:27:04', NULL, NULL),
(17, '2025-000015', 196, NULL, 1, 'Quizzes not loading questions', 'I am attempting to take the quiz on this first Course. it shows 15 questions but they will not load.', 'new', 'normal', '2025-09-24 02:57:07', '2025-09-24 02:57:07', NULL, NULL);
